import { z } from 'zod';

export const contactSchema = z.object({
    name: z.string().min(2, { message: "Nome deve ter pelo menos 2 caracteres." }),
    company: z.string().optional(),
    email: z.string().email({ message: "Email inválido." }),
    phone: z.string().min(10, { message: "Telefone deve ter pelo menos 10 caracteres." }).optional().or(z.literal('')),
    service: z.string().min(1, { message: "Selecione um serviço." }),
    details: z.string().min(10, { message: "Detalhes do projeto devem ter pelo menos 10 caracteres." }),
});

export type ContactFormData = z.infer<typeof contactSchema>;
